Page.onReady = function() {
  Page.Widgets.departmentForm.formfields.departmentName.setValidators([{
    type: VALIDATOR.REQUIRED,
    validator: true,
    errorMessage: "This field cannot be empty."
  }]);
};

Page.dialog1Opened = function ($event, widget) {
  Page.Widgets.loginForm.formfields.username.setValidators([lastNameVal]);
};

function lastNameVal(field, form) {
  if (field.value && field.value.length < 2) { //to get datavalue of widget must use field.value not field.datavalue 
    return {
      errorMessage: "Enter your full name."
    };
  }
}

Page.Widgets.employeeForm.formfields.lastname.setValidators([
  emailRequired,
  {
    type: VALIDATOR.REGEXP,
    validator: /\w+@\w+\.\w{2,3}/,
    errorMessage: "Not a Valid Email"
  }
]);

function emailRequired(field, form) {
  if (!field.value || field.value.length < 1) { //to get datavalue of widget must use field.value not field.datavalue 
    return {
      errorMessage: "Email cannot be empty."
    };
  }
}

Page.Widgets.RegistationForm.formfields.email.setAsyncValidators([emailAsync]);

function emailAsync(field, form) {
  return new Promise(function(resolve, reject) {
    if (field.value === "duplicate@example.com") { //to get datavalue of widget must use field.value not field.datavalue 
      reject({
        errorMessage: "Email already exists."
      });
    } else {
      resolve();
    }
  });
}

Page.Widgets.EmployeeForm1.formfields.passowrd.setValidators([confirmPasswordEval]);
Page.Widgets.EmployeeForm1.formfields.confirmpassword.observeOn(['password']);

function confirmPasswordEval(field, form) {
  if (field.value && form.formfields.password.value !== field.value) { //to get datavalue of widget must use field.value not field.datavalue 
    return {
      errorMessage: "Password & Confirm Password are not the same value"
    };
  }
}

